const key = 'scxml_' + String(msg.machine || 'unknown').split(' ')[0].replace(/[^A-Za-z0-9_]/g, '_');
global.set(key, {
  states: msg.states || [],
  vars: msg.vars || {},
  changed: !!msg.changed,
  event: msg.event ?? null,
  ts: Date.now()
});
return msg;

const arr = global.get('scxml_events') || [];
arr.push({
  event: msg.event ?? null,
  payload: msg.payload,
  machine: msg.machine ?? null,
  topic: msg.topic ?? null,
  ts: Date.now()
});
if (arr.length > 300) { arr.splice(0, arr.length - 300); }
global.set('scxml_events', arr);
return msg;
